// Источник: web-тест .qa/e2e/tests/profile/pr-02-edit-name.spec.ts, план .qa/e2e/specs/profile.md, кейс .qa/tests/profile/PR-02-edit-display-name.md
// Тикет #ba9c188c. Меняет имя user1 и возвращает «אקדא טסט» в конце. «reload» → уход с экрана и возврат.
import { $, expect, driver } from '@wdio/globals';
import { byText, byTextContains, byLabel, tapLabel, expectTextContains, scrollToText } from '../../helpers/ui.ts';
import { goTab } from '../../helpers/nav.ts';
import { toHome } from '../../helpers/app.ts';

const ORIGINAL_NAME = 'אקדא טסט';
const TEST_NAME = 'QA-AUTO-שם בדיקה';

function button(text: string) {
  return driver.isAndroid ? $(`//*[@text="${text}"]/ancestor-or-self::*[@clickable="true"][1]`) : byText(text);
}
async function openProfile() {
  await toHome();
  await tapLabel('מעבר לפרטים שלי');
  await (await byText('פרופיל אישי')).waitForDisplayed({ timeout: 20000 });
}
async function nameField() {
  const f = await byLabel('שם מלא');
  await f.waitForDisplayed();
  return f;
}
/** Окно уровня «עלית דרגה» может перекрыть экран — закрыть, если есть. */
async function dismissMilestone() {
  const close = await byTextContains('סגירה');
  if (await close.isDisplayed().catch(() => false)) await close.click();
}
async function setName(name: string) {
  await openProfile();
  await tapLabel('עריכת השם');
  const f = await nameField();
  await f.clearValue();
  await f.setValue(name);
  await (await button('שמירה')).click();
  await expectTextContains('שם מלא: השינוי נשמר.');
}

describe('Профиль — вошедший пользователь', () => {
  afterEach(async () => { await toHome(); });

  it('PR-02 Правка имени — видно везде, переживает перезаход; пустое и >60 символов не сохраняются #ba9c188c @data', async () => {
    try {
      // 1. Профиль → «עריכת השם» → поле «שם מלא» с текущим именем.
      await openProfile();
      await expect(byText(ORIGINAL_NAME)).toBeDisplayed(); // имя в шапке профиля (кнопка «עריכת השם»)
      await tapLabel('עריכת השם');
      const input = await nameField();
      expect(await input.getText()).toBe(ORIGINAL_NAME);

      // 2. Пусто → «שמירה» неактивна; только пробелы → неактивна; 65 символов → ошибка и неактивна.
      await input.clearValue();
      await expect(button('שמירה')).toBeDisabled();
      await input.setValue('     ');
      await expect(button('שמירה')).toBeDisabled();
      await input.clearValue();
      await input.setValue('א'.repeat(65));
      await expectTextContains('השם ארוך מדי: אפשר עד 60 תווים.');
      await expect(button('שמירה')).toBeDisabled();

      // 3. «QA-AUTO-שם בדיקה» → «שמירה».
      await input.clearValue();
      await input.setValue(TEST_NAME);
      await expect(button('שמירה')).toBeEnabled();
      await (await button('שמירה')).click();
      await expectTextContains('שם מלא: השינוי נשמר.');
      await expect(byLabel('שם מלא')).not.toBeDisplayed();

      // 4. Перезаход в профиль; «המסע שלי» и главная.
      await openProfile();
      await expect(byText(TEST_NAME)).toBeDisplayed();
      await expect(byText('Q')).toBeDisplayed(); // буква аватара
      await scrollToText('פרטי ההרשמה');
      await scrollToText('שם מלא');
      await expect(byLabel(`שם מלא: ${TEST_NAME}. מעבר לשלב כדי לשנות`)).toBeDisplayed();

      await toHome();
      await goTab('המסע שלי');
      await dismissMilestone();
      await (await byText(TEST_NAME)).waitForDisplayed({ timeout: 20000 });

      await toHome();
      await (await byTextContains(`${TEST_NAME}, מוכן לתפילה`)).waitForDisplayed({ timeout: 20000 });
    } finally {
      // 5. Уборка: вернуть «אקדא טסט».
      await dismissMilestone();
      await setName(ORIGINAL_NAME);
      await openProfile();
      await expect(byText(ORIGINAL_NAME)).toBeDisplayed(); // имя в шапке профиля (кнопка «עריכת השם»)
      await toHome();
      await (await byTextContains(`${ORIGINAL_NAME}, מוכן לתפילה`)).waitForDisplayed({ timeout: 20000 });
    }
  });
});
